function emitTelemetryFrame (event, frame, subscribers) {
  const sockets = [...subscribers.values()].map(entry => entry.socket)
  if (!sockets.length) return
  const namespace = sockets[0].nsp
  // A namespace broadcast encodes once, but targets only authenticated socket IDs.
  if (typeof namespace?.to === 'function' && sockets.every(socket => socket.nsp === namespace)) {
    namespace.to(sockets.map(socket => socket.id)).volatile.emit(event, frame)
  } else {
    for (const socket of sockets) socket.volatile.emit(event, frame)
  }
}

module.exports = { emitTelemetryFrame }
